style.css:
@-moz-document domain("app.asana.com") {
body {
    background-color: #fff0f5 !important; /* Fallback */
    background-image: 
      linear-gradient(45deg, #fbe4ec 25%, transparent 25%),
      linear-gradient(-45deg, #fbe4ec 25%, transparent 25%),
      linear-gradient(45deg, transparent 75%, #fbe4ec 75%),
      linear-gradient(-45deg, transparent 75%, #fbe4ec 75%) !important;
    background-size: 40px 40px !important;
    background-position: 0 0, 0 20px, 20px -20px, -20px 0px !important;
    font-family: 'Quicksand', 'Segoe UI', sans-serif !important;
  }

  /* Soft pastel elements */
  .Sidebar, .SidebarNav, .Topbar, .TaskPane, .TaskPane-header, .TaskPaneBody, .PageHeader, .ProjectPageHeader, .TaskRow, .TaskRow--highlighted {
    background-color: rgba(255, 255, 255, 0.85) !important;
    border-radius: 12px !important;
    backdrop-filter: blur(6px) !important;
  }

  .Sidebar {
    background-color: rgba(230, 245, 255, 0.75) !important;
  }

  .TaskName, .PageHeaderStructure-titleRow, .TaskPane-titleRow {
    font-family: 'Quicksand', 'Segoe UI', sans-serif !important;
    font-weight: 500 !important;
    color: #444 !important;
  }

  .Topbar, .PageHeader, .SidebarNav {
    background-color: rgba(255, 240, 245, 0.8) !important; /* LavenderBlush pastel */
  }

  /* Buttons and accents */
  .Button, .TopbarPageHeaderGlobalActions-button, .TaskRow:hover {
    background-color: #d3f8e2 !important; /* pastel mint */
    color: #333 !important;
    border-radius: 8px !important;
  }

  .TaskRow:hover {
    background-color: #fcd5ce !important; /* pastel peach */
  }

  * {
    box-shadow: none !important;
    border: none !important;
  }
}
